import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Header } from '../../../widgets/header';
import { Footer } from '../../../widgets/footer/ui/Footer';
import { useSimpleAuth } from '../../../app/providers/SimpleAuthProvider';
import { useFavorites } from '../../../app/providers/FavoritesProvider';
import { useCart } from '../../../app/providers/CartProvider';
import { useOrders } from '../../../app/providers/OrdersProvider';
import { AddToCartButton } from '../../../features/add-to-cart/ui/AddToCartButton';
import { orderApi } from '../../../shared/api/order';
import { adminApi } from '../../../shared/api/adminApi';
import { apiClient } from '../../../shared/api/apiClient';
import './ProfilePage.css';

export const ProfilePage: React.FC = () => {
  const { user, logout } = useSimpleAuth();
  const { favorites, removeFromFavorites } = useFavorites();
  const { addToCart } = useCart();
  const { orders } = useOrders();
  const navigate = useNavigate();
  const location = useLocation();
  const [isEditing, setIsEditing] = useState(false);
  const [myShops, setMyShops] = useState<any[]>([]);
  const [shopOrders, setShopOrders] = useState<any[]>([]);
  const [isEditingAddress, setIsEditingAddress] = useState<string | null>(null);
  const [newAddress, setNewAddress] = useState('');
  const [shopActiveTab, setShopActiveTab] = useState<'products' | 'orders'>('products');
  const [shopProducts, setShopProducts] = useState<any[]>([]);
  const [selectedShopId, setSelectedShopId] = useState<string>('');
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [editingProduct, setEditingProduct] = useState<any>(null);
  const [productFormData, setProductFormData] = useState({
    name: '',
    description: '',
    price: '',
    imageUrl: '',
    categoryName: 'ФУТБОЛКИ'
  });

  const getTabFromUrl = () => {
    const params = new URLSearchParams(location.search);
    return params.get('tab') || 'profile';
  };

  const [activeTab, setActiveTab] = useState(getTabFromUrl());

  useEffect(() => {
    setActiveTab(getTabFromUrl());
  }, [location.search]);

  useEffect(() => {
    if (user) {
      fetchMyShops();
    }
  }, [user]);

  useEffect(() => {
    if (activeTab === 'shop-dashboard' && user) {
      fetchShopOrders();
    }
  }, [activeTab, user]);

  const fetchMyShops = async () => {
    try {
      const response = await apiClient.get<any[]>('/api/shops/my');
      setMyShops(response);
      if (response.length > 0) {
        setSelectedShopId(response[0].id);
        fetchShopProducts(response[0].id);
      }
    } catch (error) {
      console.error('Failed to fetch shops:', error);
    }
  };

  const fetchShopProducts = async (shopId: string) => {
    try {
      const response = await adminApi.getProductsByShop(shopId);
      setShopProducts(response);
    } catch (error) {
      console.error('Failed to fetch shop products:', error);
    }
  };

  const fetchShopOrders = async () => {
    if (!user) return;
    try {
      const response = await orderApi.getShopOrders(user.email);
      setShopOrders(response);
    } catch (error) {
      console.error('Failed to fetch shop orders:', error);
    }
  };

  const handleUpdateAddress = async (orderId: string) => {
    try {
      await orderApi.updateAddress(orderId, newAddress);
      setIsEditingAddress(null);
      // Reload orders
      window.location.reload(); // Simple way to refresh data
    } catch (error) {
      console.error('Failed to update address:', error);
    }
  };

  const handleCancelOrder = async (orderId: string) => {
    if (!window.confirm('Вы уверены, что хотите отменить заказ?')) return;
    try {
      await orderApi.cancelOrder(orderId);
      window.location.reload();
    } catch (error) {
      console.error('Failed to cancel order:', error);
    }
  };

  const handleUpdateOrderStatus = async (orderId: string, status: string) => {
    try {
      await orderApi.updateStatus(orderId, status);
      fetchShopOrders();
    } catch (error) {
      console.error('Failed to update status:', error);
    }
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const data = {
      ...productFormData,
      price: parseInt(productFormData.price),
      stock: 100,
      material: 'Cotton',
      isActive: true
    };

    try {
      if (editingProduct) {
        await adminApi.updateProduct(editingProduct.id, data as any);
      } else {
        await adminApi.addProduct(selectedShopId, data);
      }
      fetchShopProducts(selectedShopId);
      setIsAddingProduct(false);
      setEditingProduct(null);
    } catch (error) {
      console.error('Failed to save product:', error);
    }
  };

  const handleEditProduct = (product: any) => {
    setEditingProduct(product);
    setProductFormData({
      name: product.name,
      description: product.description,
      price: product.price.toString(),
      imageUrl: product.image,
      categoryName: typeof product.category === 'string' ? product.category : product.category?.name || 'ФУТБОЛКИ'
    });
    setIsAddingProduct(true);
  };

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    birthDate: '',
    gender: '',
    city: '',
    street: '',
    house: '',
    phone: ''
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleGenderChange = (gender: string) => {
    setFormData(prev => ({ ...prev, gender }));
  };

  const handleSave = () => {
    setIsEditing(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const handleTabChange = (tab: string) => {
    navigate(`/profile?tab=${tab}`);
  };

  const handleGoHome = () => {
    navigate('/');
  };

  const handleAddToCartFromFavorites = async (product: any) => {
    console.log('ProfilePage - Adding to cart from favorites:', product.id);
    try {
      await addToCart(product);
      console.log('ProfilePage - Successfully added to cart, removing from favorites');
      await removeFromFavorites(product.id);
    } catch (error) {
      console.error('ProfilePage - Failed to add to cart:', error);
    }
  };

  const renderContent = () => {
    switch(activeTab) {
      case 'profile':
        return (
          <div className="profile-section">
            <h2 className="section-title">Мои данные</h2>

            <div className="info-block">
              <h3 className="block-title">Личная информация</h3>

              <div className="form-row">
                <div className="form-group">
                  <label>Имя *</label>
                  {isEditing ? (
                    <input
                      type="text"
                      name="firstName"
                      value={formData.firstName}
                      onChange={handleInputChange}
                      placeholder="Введите имя"
                    />
                  ) : (
                    <p className="info-value">{formData.firstName}</p>
                  )}
                </div>

                <div className="form-group">
                  <label>Фамилия *</label>
                  {isEditing ? (
                    <input
                      type="text"
                      name="lastName"
                      value={formData.lastName}
                      onChange={handleInputChange}
                      placeholder="Введите фамилию"
                    />
                  ) : (
                    <p className="info-value">{formData.lastName}</p>
                  )}
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Дата рождения *</label>
                  {isEditing ? (
                    <input
                      type="date"
                      name="birthDate"
                      value={formData.birthDate}
                      onChange={handleInputChange}
                    />
                  ) : (
                    <p className="info-value">{formData.birthDate}</p>
                  )}
                </div>

                <div className="form-group">
                  <label>Пол</label>
                  {isEditing ? (
                    <div className="gender-options">
                      <label className="gender-label">
                        <input
                          type="radio"
                          name="gender"
                          checked={formData.gender === 'male'}
                          onChange={() => handleGenderChange('male')}
                        />
                        <span>Мужской</span>
                      </label>
                      <label className="gender-label">
                        <input
                          type="radio"
                          name="gender"
                          checked={formData.gender === 'female'}
                          onChange={() => handleGenderChange('female')}
                        />
                        <span>Женский</span>
                      </label>
                    </div>
                  ) : (
                    <p className="info-value">
                      {formData.gender === 'male' ? 'Мужской' : 'Женский'}
                    </p>
                  )}
                </div>
              </div>
            </div>

            <div className="info-block">
              <h3 className="block-title">Адрес</h3>

              <div className="form-row">
                <div className="form-group">
                  <label>Город *</label>
                  {isEditing ? (
                    <input
                      type="text"
                      name="city"
                      value={formData.city}
                      onChange={handleInputChange}
                      placeholder="Введите город"
                    />
                  ) : (
                    <p className="info-value">{formData.city}</p>
                  )}
                </div>

                <div className="form-group">
                  <label>Улица *</label>
                  {isEditing ? (
                    <input
                      type="text"
                      name="street"
                      value={formData.street}
                      onChange={handleInputChange}
                      placeholder="Введите улицу"
                    />
                  ) : (
                    <p className="info-value">{formData.street}</p>
                  )}
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Дом *</label>
                  {isEditing ? (
                    <input
                      type="text"
                      name="house"
                      value={formData.house}
                      onChange={handleInputChange}
                      placeholder="Введите номер дома"
                    />
                  ) : (
                    <p className="info-value">{formData.house}</p>
                  )}
                </div>
              </div>
            </div>

            <div className="info-block">
              <h3 className="block-title">Номер телефона</h3>
              <div className="form-group">
                {isEditing ? (
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    placeholder="+7(***)-***-**-**"
                  />
                ) : (
                  <p className="info-value phone">{formData.phone}</p>
                )}
              </div>
            </div>

            {!isEditing && (
              <button className="edit-btn mobile-edit" onClick={() => setIsEditing(true)}>
                <svg width="18" height="18" viewBox="0 0 16 16" fill="currentColor">
                  <path d="M12.854.146a.5.5 0 0 0-.707 0L10.5 1.793 14.207 5.5l1.647-1.646a.5.5 0 0 0 0-.708l-3-3zm.646 6.061L9.793 2.5 3.293 9H3.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.207l6.5-6.5zm-7.468 7.468A.5.5 0 0 1 6 13.5V13h-.5a.5.5 0 0 1-.5-.5V12h-.5a.5.5 0 0 1-.5-.5V11h-.5a.5.5 0 0 1-.5-.5V10h-.5a.499.499 0 0 1-.175-.032l-.179.178a.5.5 0 0 0-.11.168l-2 5a.5.5 0 0 0 .65.65l5-2a.5.5 0 0 0 .168-.11l.178-.178z"/>
                </svg>
                Изменить
              </button>
            )}
          </div>
        );
 case 'favorites':
  return (
    <div className="profile-section">
      <h2 className="section-title">Избранное</h2>
      {!Array.isArray(favorites) || favorites.length === 0 ? (
        <div className="empty-state">
          <svg width="60" height="60" viewBox="0 0 16 16" fill="#ccc">
            <path fillRule="evenodd" d="M8 1.314C12.438-3.248 23.534 4.735 8 15-7.534 4.736 3.562-3.248 8 1.314z"/>
          </svg>
          <p>В избранном пока ничего нет</p>
          <button className="home-link" onClick={handleGoHome}>
            Перейти к покупкам
          </button>
        </div>
      ) : (
        <div className="favorites-grid">
          {Array.isArray(favorites) && favorites.map(product => (
            <div key={product.id} className="favorite-card">
              <div className="favorite-image">
                <img src={product.image} alt={product.name} />
              </div>
              <div className="favorite-info">
                <div className="favorite-details">
                  <h3 className="favorite-brand">{product.brand}</h3>
                  <p className="favorite-name">{product.name}</p>
                </div>
                <p className="favorite-price">{product.price?.toLocaleString() ?? 0} ₽</p>
              </div>
              <button 
                className="remove-favorite"
                onClick={() => removeFromFavorites(product.id)}
              >
                ×
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
      case 'orders':
  return (
    <div className="profile-section">
      <h2 className="section-title">Мои заказы</h2>
      {orders.length === 0 ? (
        <div className="empty-state">
          <svg width="80" height="80" viewBox="0 0 24 24" fill="#ccc">
            <path d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zM1 2v2h2l3.6 7.59-1.35 2.45c-.16.28-.25.61-.25.96 0 1.1.9 2 2 2h12v-2H7.42c-.14 0-.25-.11-.25-.25l.03-.12.9-1.63h7.45c.75 0 1.41-.41 1.75-1.03l3.58-6.49c.08-.14.12-.31.12-.48 0-.55-.45-1-1-1H5.21l-.94-2H1zm16 16c-1.1 0-1.99.9-1.99 2s.89 2 1.99 2 2-.9 2-2-.9-2-2-2z"/>
          </svg>
          <p>У вас пока нет заказов</p>
          <button className="home-link" onClick={handleGoHome}>
            Перейти к покупкам
          </button>
        </div>
      ) : (
        <div className="orders-list">
          {orders.map(order => (
            <div key={order.id} className="order-card">
              <div className="order-header">
                <div className="order-info">
                  <span className="order-number">Заказ #{order.id.slice(-6)}</span>
                  <span className="order-date">{new Date(order.date).toLocaleDateString('ru-RU')}</span>
                </div>
                <div className={`order-status status-${order.status}`}>
                  {(order.status === 'pending' || order.status === 'CREATED') && 'Ожидает оплаты'}
                  {(order.status === 'processing' || order.status === 'CONFIRMED') && 'В работе'}
                  {(order.status === 'shipped' || order.status === 'SHIPPED') && 'Отправлен'}
                  {(order.status === 'delivered' || order.status === 'DELIVERED') && 'Доставлен'}
                  {(order.status === 'cancelled' || order.status === 'CANCELLED') && 'Отменен'}
                  {order.status === 'REFUNDED' && 'Возврат'}
                </div>
              </div>
              <div className="order-items">
                {order.items.slice(0, 3).map(item => (
                  <div key={item.id} className="order-item">
                    <img src={item.product.image} alt={item.product.name} className="order-item-image" />
                    <div className="order-item-info">
                      <div className="order-item-name">{item.product.name}</div>
                      <div className="order-item-brand">{item.product.brand}</div>
                      <div className="order-item-price">{(item.product.price || 0).toLocaleString()} ₽</div>
                    </div>
                  </div>
                ))}
                {order.items.length > 3 && (
                  <div className="order-more">и еще {order.items.length - 3} товаров</div>
                )}
              </div>
              <div className="order-footer">
                <div className="order-total">
                  <span>Итого:</span>
                  <span>{order.total.toLocaleString()} ₽</span>
                </div>
                <div className="order-actions-customer">
                  {isEditingAddress === order.id ? (
                    <div className="address-edit-form">
                      <input 
                        type="text" 
                        value={newAddress} 
                        onChange={(e) => setNewAddress(e.target.value)}
                        placeholder="Новый адрес"
                      />
                      <button onClick={() => handleUpdateAddress(order.id)}>ОК</button>
                      <button onClick={() => setIsEditingAddress(null)}>Отмена</button>
                    </div>
                  ) : (
                    <>
                      {['CREATED', 'CONFIRMED', 'pending', 'processing'].includes(order.status) && (
                        <button 
                          className="edit-address-btn"
                          onClick={() => {
                            setIsEditingAddress(order.id);
                            setNewAddress(order.adress || order.address || '');
                          }}
                        >
                          Изменить адрес
                        </button>
                      )}
                      {['CREATED', 'pending'].includes(order.status) && (
                        <button 
                          className="cancel-order-btn"
                          onClick={() => handleCancelOrder(order.id)}
                        >
                          Отменить заказ
                        </button>
                      )}
                    </>
                  )}
                </div>
                <button className="order-details-btn" onClick={() => navigate(`/order/${order.id}`)}>
                  Подробнее
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
      case 'notifications':
        return (
          <div className="profile-section">
            <h2 className="section-title">Уведомления</h2>
            <div className="empty-state">
              <p>Новых уведомлений нет</p>
            </div>
          </div>
        );
      case 'seller':
        return (
          <div className="profile-section">
            <h2 className="section-title">Стать продавцом</h2>
            <div className="empty-state">
            </div>
          </div>
        );
      case 'shop-dashboard':
        return (
          <div className="profile-section">
            <h2 className="section-title">Кабинет магазина</h2>

            <div className="shop-dashboard-tabs">
              <button 
                className={`shop-tab ${shopActiveTab === 'products' ? 'active' : ''}`}
                onClick={() => setShopActiveTab('products')}
              >
                Товары
              </button>
              <button 
                className={`shop-tab ${shopActiveTab === 'orders' ? 'active' : ''}`}
                onClick={() => setShopActiveTab('orders')}
              >
                Заказы магазинов
              </button>
            </div>

            {shopActiveTab === 'products' && (
              <div className="shop-products-section">
                <div className="content-header" style={{ marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div className="shop-selector">
                    <label style={{ marginRight: '10px' }}>Магазин:</label>
                    <select 
                      value={selectedShopId} 
                      onChange={(e) => {
                        setSelectedShopId(e.target.value);
                        fetchShopProducts(e.target.value);
                      }}
                      style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
                    >
                      {myShops.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <button className="add-btn" onClick={() => {
                    setIsAddingProduct(true);
                    setEditingProduct(null);
                    setProductFormData({ name: '', description: '', price: '', imageUrl: '', categoryName: 'ФУТБОЛКИ' });
                  }}>Добавить товар</button>
                </div>

                <div className="products-grid-admin">
                  {shopProducts.map(p => (
                    <div key={p.id} className="admin-product-card">
                      <img src={p.image} alt={p.name} />
                      <div className="admin-product-info">
                        <h4>{p.name}</h4>
                        <p>{p.price} ₽</p>
                        <div className="admin-product-actions">
                          <button onClick={() => handleEditProduct(p)}>Изм.</button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {isAddingProduct && (
                  <div className="modal-overlay">
                    <div className="modal-content">
                      <h3>{editingProduct ? 'Изменить товар' : 'Новый товар'}</h3>
                      <form onSubmit={handleProductSubmit}>
                        <div className="form-group">
                          <label>Название</label>
                          <input type="text" value={productFormData.name} onChange={e => setProductFormData({...productFormData, name: e.target.value})} required />
                        </div>
                        <div className="form-group">
                          <label>Цена</label>
                          <input type="number" value={productFormData.price} onChange={e => setProductFormData({...productFormData, price: e.target.value})} required />
                        </div>
                        <div className="form-group">
                          <label>Описание</label>
                          <textarea value={productFormData.description} onChange={e => setProductFormData({...productFormData, description: e.target.value})} />
                        </div>
                        <div className="form-group">
                          <label>URL изображения</label>
                          <input type="text" value={productFormData.imageUrl} onChange={e => setProductFormData({...productFormData, imageUrl: e.target.value})} />
                        </div>
                        <div className="form-group">
                          <label>Категория</label>
                          <select value={productFormData.categoryName} onChange={e => setProductFormData({...productFormData, categoryName: e.target.value})}>
                            <option value="ФУТБОЛКИ">ФУТБОЛКИ</option>
                            <option value="ЗИПКИ">ЗИПКИ</option>
                          </select>
                        </div>
                        <div className="modal-actions">
                          <button type="submit" className="save-btn">Сохранить</button>
                          <button type="button" className="cancel-btn" onClick={() => setIsAddingProduct(false)}>Отмена</button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}
              </div>
            )}

            {shopActiveTab === 'orders' && (
              <div className="shop-orders-section">
                {shopOrders.length === 0 ? <p>Нет заказов для ваших магазинов</p> : (
                  <div className="shop-orders-list">
                    {shopOrders.map(order => (
                      <div key={order.id} className="shop-order-card">
                        <div className="shop-order-header">
                          <span>Заказ #{order.id.slice(-6)}</span>
                          <select 
                            value={order.status} 
                            onChange={(e) => handleUpdateOrderStatus(order.id, e.target.value)}
                            className={`status-select status-${order.status}`}
                          >
                            <option value="CREATED">CREATED (Новый)</option>
                            <option value="CONFIRMED">CONFIRMED (В работе)</option>
                            <option value="SHIPPED">SHIPPED (Отправлен)</option>
                            <option value="DELIVERED">DELIVERED (Доставлен)</option>
                            <option value="CANCELLED">CANCELLED (Отменен)</option>
                          </select>
                        </div>
                        <div className="shop-order-items">
                          {order.items.map((item: any) => (
                            <div key={item.id} className="shop-order-item">
                              <span>{item.product.name} x{item.quantity}</span>
                              <span>{item.priceAtPurchase * item.quantity} ₽</span>
                            </div>
                          ))}
                        </div>
                        <div className="shop-order-footer">
                          <span>Адрес: {order.adress}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="profile-page">
      <Header 
        title="ЛИЧНЫЙ КАБИНЕТ" 
        subtitle="" 
        backgroundImage="/images-main/profile-header.jpg" 
        showOverlay={false} 
      />

      <main className="profile-main">
        <div className="profile-container">
          <div className="profile-layout">
            <aside className="profile-menu">
              <div className="menu-items">
                <button 
                  className={`menu-item ${activeTab === 'profile' ? 'active' : ''}`}
                  onClick={() => handleTabChange('profile')}
                >
                  <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M3 14s-1 0-1-1 1-4 6-4 6 3 6 4-1 1-1 1H3zm5-6a3 3 0 1 0 0-6 3 3 0 0 0 0 6z"/>
                  </svg>
                  Мои данные
                </button>

                <button 
                  className={`menu-item ${activeTab === 'orders' ? 'active' : ''}`}
                  onClick={() => handleTabChange('orders')}
                >
                  <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M8 1a2.5 2.5 0 0 1 2.5 2.5V4h-5v-.5A2.5 2.5 0 0 1 8 1zm3.5 3v-.5a3.5 3.5 0 1 0-7 0V4H1v10a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V4h-3.5z"/>
                  </svg>
                  Мои заказы
                </button>

                <button 
                  className={`menu-item ${activeTab === 'notifications' ? 'active' : ''}`}
                  onClick={() => handleTabChange('notifications')}
                >
                  <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M8 16a2 2 0 0 0 2-2H6a2 2 0 0 0 2 2zM8 1.918l-.797.161A4.002 4.002 0 0 0 4 6c0 .628-.134 2.197-.459 3.742-.16.767-.376 1.566-.663 2.258h10.244c-.287-.692-.502-1.49-.663-2.258C12.134 8.197 12 6.628 12 6a4.002 4.002 0 0 0-3.203-3.92L8 1.917zM14.22 12c.223.447.481.801.78 1H1c.299-.199.557-.553.78-1C2.68 10.2 3 6.88 3 6c0-2.42 1.72-4.44 4.005-4.901a1 1 0 1 1 1.99 0A5.002 5.002 0 0 1 13 6c0 .88.32 4.2 1.22 6z"/>
                  </svg>
                  Уведомления
                </button>

                <button 
                  className={`menu-item ${activeTab === 'favorites' ? 'active' : ''}`}
                  onClick={() => handleTabChange('favorites')}
                >
                  <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                    <path fillRule="evenodd" d="M8 1.314C12.438-3.248 23.534 4.735 8 15-7.534 4.736 3.562-3.248 8 1.314z"/>
                  </svg>
                  Избранное
                  {Array.isArray(favorites) && favorites.length > 0 && <span className="menu-badge">{favorites.length}</span>}
                </button>

                <button 
                  className={`menu-item ${activeTab === 'seller' ? 'active' : ''}`}
                  onClick={() => handleTabChange('seller')}
                >
                  <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M12.854.146a.5.5 0 0 0-.707 0L10.5 1.793 14.207 5.5l1.647-1.646a.5.5 0 0 0 0-.708l-3-3zm.646 6.061L9.793 2.5 3.293 9H3.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.207l6.5-6.5zm-7.468 7.468A.5.5 0 0 1 6 13.5V13h-.5a.5.5 0 0 1-.5-.5V12h-.5a.5.5 0 0 1-.5-.5V11h-.5a.5.5 0 0 1-.5-.5V10h-.5a.499.499 0 0 1-.175-.032l-.179.178a.5.5 0 0 0-.11.168l-2 5a.5.5 0 0 0 .65.65l5-2a.5.5 0 0 0 .168-.11l.178-.178z"/>
                  </svg>
                  Стать продавцом
                </button>

                {myShops.length > 0 && (
                  <button 
                    className={`menu-item ${activeTab === 'shop-dashboard' ? 'active' : ''}`}
                    onClick={() => handleTabChange('shop-dashboard')}
                    style={{ marginTop: '10px', color: '#10b981', fontWeight: 'bold' }}
                  >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>
                      <polyline points="9 22 9 12 15 12 15 22"/>
                    </svg>
                    Кабинет магазина
                  </button>
                )}

                {(user?.roles?.includes('ADMIN') || user?.roles?.includes('SELLER')) && (
                  <button 
                    className="menu-item admin-link"
                    onClick={() => navigate('/admin')}
                    style={{ marginTop: '10px', color: '#6366f1', fontWeight: 'bold' }}
                  >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/>
                    </svg>
                    Админ панель
                  </button>
                )}
              </div>

              <button className="logout-btn" onClick={handleLogout}>
                <svg width="18" height="18" viewBox="0 0 16 16" fill="currentColor">
                  <path fillRule="evenodd" d="M10 12.5a.5.5 0 0 1-.5.5h-8a.5.5 0 0 1-.5-.5v-9a.5.5 0 0 1 .5-.5h8a.5.5 0 0 1 .5.5v2a.5.5 0 0 0 1 0v-2A1.5 1.5 0 0 0 9.5 2h-8A1.5 1.5 0 0 0 0 3.5v9A1.5 1.5 0 0 0 1.5 14h8a1.5 1.5 0 0 0 1.5-1.5v-2a.5.5 0 0 0-1 0v2z"/>
                  <path fillRule="evenodd" d="M15.854 8.354a.5.5 0 0 0 0-.708l-3-3a.5.5 0 0 0-.708.708L14.293 7.5H5.5a.5.5 0 0 0 0 1h8.793l-2.147 2.146a.5.5 0 0 0 .708.708l3-3z"/>
                </svg>
                Выйти
              </button>
            </aside>

            <div className="profile-content-wrapper">
              <div className="profile-header">
                <div className="profile-header-left">
                  <button className="back-home-btn" onClick={handleGoHome}>
                    <svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
                      <path fillRule="evenodd" d="M11.354 1.646a.5.5 0 0 1 0 .708L5.707 8l5.647 5.646a.5.5 0 0 1-.708.708l-6-6a.5.5 0 0 1 0-.708l6-6a.5.5 0 0 1 .708 0z"/>
                    </svg>
                    На главную
                  </button>
                  <h1 className="profile-title">Личный кабинет</h1>
                </div>
                {activeTab === 'profile' && !isEditing && (
                  <button className="edit-btn desktop-edit" onClick={() => setIsEditing(true)}>
                    <svg width="18" height="18" viewBox="0 0 16 16" fill="currentColor">
                      <path d="M12.854.146a.5.5 0 0 0-.707 0L10.5 1.793 14.207 5.5l1.647-1.646a.5.5 0 0 0 0-.708l-3-3zm.646 6.061L9.793 2.5 3.293 9H3.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.5h.5a.5.5 0 0 1 .5.5v.207l6.5-6.5zm-7.468 7.468A.5.5 0 0 1 6 13.5V13h-.5a.5.5 0 0 1-.5-.5V12h-.5a.5.5 0 0 1-.5-.5V11h-.5a.5.5 0 0 1-.5-.5V10h-.5a.499.499 0 0 1-.175-.032l-.179.178a.5.5 0 0 0-.11.168l-2 5a.5.5 0 0 0 .65.65l5-2a.5.5 0 0 0 .168-.11l.178-.178z"/>
                    </svg>
                    Изменить
                  </button>
                )}
                {activeTab === 'profile' && isEditing && (
                  <div className="edit-actions">
                    <button className="save-btn" onClick={handleSave}>Сохранить</button>
                    <button className="cancel-btn" onClick={() => setIsEditing(false)}>Отмена</button>
                  </div>
                )}
              </div>

              {renderContent()}
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};
